import { useEffect, useState } from 'react';
import './Profile.css';

import {
  getCountries,
  createCountry,
  updateCountry,
  deleteCountry
} from '../../services/countryService';

import {
  getCities,
  createCity,
  updateCity,
  deleteCity
} from '../../services/cityService';

import {
  getCategories,
  createCategory,
  updateCategory,
  deleteCategory
} from '../../services/categoryService';

import {
  getTourOperators,
  createTourOperator,
  updateTourOperator,
  deleteTourOperator
} from '../../services/tourOperatorService';

const AdminPanel = () => {
  /* ===== DATA ===== */
  const [countries, setCountries] = useState([]);
  const [cities, setCities] = useState([]);
  const [categories, setCategories] = useState([]);
  const [operators, setOperators] = useState([]);

  /* ===== FORM STATE ===== */
  const [newCountry, setNewCountry] = useState('');
  const [newCity, setNewCity] = useState('');
  const [cityCountryId, setCityCountryId] = useState('');
  const [newCategory, setNewCategory] = useState('');
  const [newOperator, setNewOperator] = useState('');

  /* ===== LOAD ===== */
  useEffect(() => {
    loadAll();
  }, []);

  const loadAll = async () => {
    await Promise.all([
      loadCountries(),
      loadCities(),
      loadCategories(),
      loadOperators()
    ]);
  };

  const loadCountries = async () => {
    setCountries(await getCountries());
  };

  const loadCities = async () => {
    setCities(await getCities());
  };

  const loadCategories = async () => {
    setCategories(await getCategories());
  };

  const loadOperators = async () => {
    setOperators(await getTourOperators());
  };

  return (
    <div className="page">
      <div className="page-container">
        <h1 className="page-title">Панель администратора</h1>

        <div className="admin-grid">

          {/* ===== COUNTRIES ===== */}
          <section className="admin-card">
            <h2>Страны</h2>

            <input
              placeholder="Название страны"
              value={newCountry}
              onChange={e => setNewCountry(e.target.value)}
            />

            <button
              className="admin-btn"
              onClick={async () => {
                if (!newCountry.trim()) return;
                await createCountry(newCountry);
                setNewCountry('');
                loadCountries();
              }}
            >
              Добавить
            </button>

            <div className="admin-list">
              {countries.map(c => (
                <div key={c.id} className="admin-item">
                  <span>{c.name}</span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/pen.svg"
                      onClick={async () => {
                        const name = prompt('Новое название', c.name);
                        if (!name) return;
                        await updateCountry(c.id, name);
                        loadCountries();
                      }}
                    />
                    <img
                      src="/assets/svg/bin.svg"
                      onClick={async () => {
                        if (!window.confirm('Удалить страну?')) return;
                        await deleteCountry(c.id);
                        loadCountries();
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== CITIES ===== */}
          <section className="admin-card">
            <h2>Города</h2>

            <input
              placeholder="Название города"
              value={newCity}
              onChange={e => setNewCity(e.target.value)}
            />

            <select
              value={cityCountryId}
              onChange={e => setCityCountryId(e.target.value)}
            >
              <option value="">Страна</option>
              {countries.map(c => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>

            <button
              className="admin-btn"
              onClick={async () => {
                if (!newCity || !cityCountryId) return;
                await createCity({
                  name: newCity,
                  countryId: Number(cityCountryId)
                });
                setNewCity('');
                setCityCountryId('');
                loadCities();
              }}
            >
              Добавить
            </button>

            <div className="admin-list">
              {cities.map(city => (
                <div key={city.id} className="admin-item">
                  <span>
                    {city.name} ({city.country?.name})
                  </span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/bin.svg"
                      onClick={async () => {
                        if (!window.confirm('Удалить город?')) return;
                        await deleteCity(city.id);
                        loadCities();
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== CATEGORIES ===== */}
          <section className="admin-card">
            <h2>Категории</h2>

            <input
              placeholder="Название категории"
              value={newCategory}
              onChange={e => setNewCategory(e.target.value)}
            />

            <button
              className="admin-btn"
              onClick={async () => {
                if (!newCategory.trim()) return;
                await createCategory(newCategory);
                setNewCategory('');
                loadCategories();
              }}
            >
              Добавить
            </button>

            <div className="admin-list">
              {categories.map(cat => (
                <div key={cat.id} className="admin-item">
                  <span>{cat.name}</span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/bin.svg"
                      onClick={async () => {
                        if (!window.confirm('Удалить категорию?')) return;
                        await deleteCategory(cat.id);
                        loadCategories();
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* ===== OPERATORS ===== */}
          <section className="admin-card">
            <h2>Туроператоры</h2>

            <input
              placeholder="Название туроператора"
              value={newOperator}
              onChange={e => setNewOperator(e.target.value)}
            />

            <button
              className="admin-btn"
              onClick={async () => {
                if (!newOperator.trim()) return;
                await createTourOperator(newOperator);
                setNewOperator('');
                loadOperators();
              }}
            >
              Добавить
            </button>

            <div className="admin-list">
              {operators.map(op => (
                <div key={op.id} className="admin-item">
                  <span>{op.name}</span>
                  <div className="admin-actions">
                    <img
                      src="/assets/svg/bin.svg"
                      onClick={async () => {
                        if (!window.confirm('Удалить туроператора?')) return;
                        await deleteTourOperator(op.id);
                        loadOperators();
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </section>

        </div>

        <button className="admin-report-btn">
          Скачать PDF-отчёт
        </button>
      </div>
    </div>
  );
};

export default AdminPanel;
